"""Human-readable evidence report; unrun/failed gates remain explicitly open."""
from pathlib import Path
from datetime import datetime,timezone
import json,html,hashlib,shutil
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/projects/proje-15cce2de02';REP=OUT/'reports'
def read(p,default=None):
    return json.loads(Path(p).read_text(encoding='utf-8-sig')) if Path(p).exists() else default
def esc(x):return html.escape(str(x))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def fmt(x,d=5):return 'henüz yok' if x is None else f'{x:.{d}g}'
def main():
    reviewed={}
    for p in sorted(REP.glob('v3_diagnostic_review_*.json')):
        for c in read(p)['cases']:reviewed[c['case']]=c
    cases=[]
    for folder in sorted((OUT/'simulations').glob('v3_*')):
        status=read(folder/'run_status.json');metrics=read(folder/'prediction_metrics.json')
        if not status:continue
        label='native tamamlandı' if status.get('exit_code')==0 else 'başarısız / durduruldu'
        if (folder/'manual_stop_request.json').exists():label='kontrollü tanı bütçesinde durduruldu'
        if status.get('status')=='interrupted_between_sessions':label='oturumlar arasında kesildi; başarılı çıkış bilinmiyor'
        cp=reviewed.get(folder.name,{}).get('original_table_comparison',{}).get('all',{}).get('RMSE')
        cases.append({'case':folder.name,'status':label,'run':status,'metrics':metrics,'Cp_RMSE':cp,'reviewed_after_freeze':folder.name in reviewed,
            'arithmetic_change':read(folder/'controlled_trial.json',read(folder/'continuation_rationale.json',{}))})
    rows=''
    for c in cases:
        m=c['metrics'] or {};checks=m.get('checks',{});numerical=bool(checks) and all(checks.values())
        firstorder='firstorder' in c['case']
        cptext='yalnız sayısal tanı' if firstorder else fmt(c['Cp_RMSE'],6)
        verdict='geçti (1. mertebe tanı)' if numerical and firstorder else ('geçti' if numerical else 'geçmedi')
        rows+=f'<tr><td><a href="../simulations/{esc(c["case"])}/configuration_overrides.json">{esc(c["case"])}</a><small>{esc(c["status"])}</small></td><td>{fmt(m.get("field_checkpoint_iteration"),7)}</td><td>{fmt(m.get("density_log10_residual"),6)}</td><td>{fmt(m.get("CL_final200_range"),4)}<br>{fmt(m.get("CD_final200_range"),4)}</td><td>{fmt(m.get("max_wall_yplus"),5)}</td><td>{cptext}</td><td class="bad">{verdict}</td></tr>'
    meshrows=''
    for name in ['v3_cgrid_coarse','v3_cgrid_medium','v3_cgrid_fine']:
        d=OUT/'simulations'/name;b=read(d/'build_metadata.json',{});a=read(d/'independent_cgrid_audit.json',{});n=a.get('near_block_design',{})
        meshrows+=f'<tr><td>{esc(name)}</td><td>{b.get("cells","—"):,}</td><td>{fmt(n.get("first_m"),4)}</td><td>{fmt(n.get("cap_m"),4)}</td><td>{n.get("layers","—")}</td><td>{fmt(n.get("thickness_m"),3)}</td><td>{"geçti" if a.get("geometry_mesh_checks_passed") else "açık"}</td></tr>'
    regional=read(REP/'prediction_v3_cgrid_interfacer4_summary.json',{})
    r4rows=''
    for a in regional.get('levels',[]):
        le=a['LE_height_ratio_max_before_after'];te=a['TE_height_ratio_max_before_after']
        worst=a['global_worst']
        r4rows+=f'<tr><td>{esc(a["case"].rsplit("_",1)[-1])}</td><td>{a["cells"]:,}</td><td>{a["max_skew_before"]:.4f} → {a["max_skew_after"]:.4f}</td><td>{le[0]:.2f} → {le[1]:.2f}<br>{te[0]:.2f} → {te[1]:.2f}</td><td>{worst["angle_min_max_deg"][0]:.2f}°<br>x/c={worst["center_m"][0]:.3f}</td></tr>'
    freezes=' · '.join(f'<a href="{p.name}">Kıyas {p.stem.rsplit("_",1)[-1]}</a>' for p in sorted(REP.glob('v3_diagnostic_review_*.json')))
    now=datetime.now(timezone.utc).isoformat()
    doc=f'''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kaynaklı CFD teşhisi ve C-grid</title>
<style>body{{font:16px/1.6 Segoe UI,Arial,sans-serif;color:#172d3e;background:#f3f6f8;margin:0}}main{{max-width:1180px;margin:auto;padding:30px}}section{{background:white;padding:22px 26px;margin:20px 0;border-radius:12px}}h1{{font-size:30px;line-height:1.2}}h2{{font-size:22px}}.bad{{color:#a13228}}.badge{{background:#fee4de;color:#87251d;padding:10px 16px;border-radius:8px;display:inline-block;font-weight:600}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{padding:10px;text-align:left;border-bottom:1px solid #dce3e9;vertical-align:top}}th{{background:#eef3f6}}small{{display:block;color:#5e6f7b}}img{{max-width:100%;height:auto}}a{{color:#165e8c}}.scroll{{overflow:auto}}code{{font-size:13px}}.note{{background:#edf4f9;padding:12px;border-left:4px solid #4485aa}}footer{{font-size:13px;color:#617383}}</style>
<main><h1>RAE2822: kaynak araştırmasıyla CFD teşhisi</h1><p>Kaynak geometriden kör CFD sınaması projesi · 19 Ekim 2026</p><span class="badge">Asgari fiziksel yeterlilik henüz geçmedi</span>
<section><h2>Ne değişti?</h2><p>Deneme sayısını artırmadan önce Gmsh kılavuzu, NASA ağ/koşul arşivi, Diskin–Thomas gradyan çalışması, SU2'nin RAE2822 doğrulama makalesi ve gerçek v8.5.0 kaynak kodu incelendi. Kaynak noktaları yeniden tasarlanmadı. Sabit 0,01c katmanın yerine 0,06c açık normal blok ve ortak iç iz kesiti olan üç C-grid üretildi.</p><p>Yayımlanmış NASA 369×65 ağı da koordinatları değiştirilmeden gerçek native SU2 RANS/SA ile çözüldü. Bu kontrolün geometri temsili ve yaklaşık20–27c dış sınırı, yeni C-grid'in r2 eğrisi ve200c sınırından farklıdır. Farkı yalnız ağ tipine atfetmek doğru olmaz.</p><p class="note">Ayrı analiz geçmişi hedef deney sonuçları verilmeden geometri ve sayısal alanları denetledi. Ana ajan önceki deney değerlendirmesini biliyor. Bu devam çalışması yeni bağımsız kör doğrulama veya güvenli dosya yalıtımı değildir.</p></section>
<section><h2>Gerçek çözümler ve değişmeyen eşikler</h2><p>Her satırdaki alan, aynı numaralı yüzey/hacim/restart üçlüsüne ve geçmiş satırına dayanır. Son200 CL aralığı≤5e−5, CD aralığı≤2e−6; yoğunluk kalıntısı≤−8 ve max y+&lt;1. Deney Cp RMSE sınırı0,03; diğer noktasal ve şok kapıları da ayrıca korunur. Başarısız veya yakınsamamış alan mühendislik tahmini olarak kullanılamaz.</p><div class="scroll"><table><tr><th>Deneme / kayıt</th><th>Alan adımı</th><th>log kalıntı</th><th>Son200 CL / CD aralığı</th><th>max y+</th><th>Cp RMSE,103 nokta</th><th>Birleşik dar sayısal ekran</th></tr>{rows}</table></div><p>Cp hücresi henüz yok ise son tahmin mühürlenip puanlanmamıştır. Genel kabul, bu tablodaki tek bir ekran değildir: aynı ailede üç yakınsamış ağ, bölgesel normal çözünürlük, uzak alan, deney ve kapsam birlikte gerekir. Orta/ince yeni CFD ve400c duyarlılığı tamamlanmadan minimum=false kalır.</p></section>
<section><h2>Konuma göre üretilen ağ</h2><div class="scroll"><table><tr><th>Ağ</th><th>Hücre</th><th>İlk uzaklık,m</th><th>Dış normal adım tavanı,m</th><th>Normal hücre</th><th>Blok kapsamı,c</th><th>Geometri/topoloji</th></tr>{meshrows}</table></div><p>Kaynak r2 B-spline üzerindeki duvar düğümlerinin eğriye uzaklığı sayısal olarak sıfır; CFD'nin düz kenarlı çokgen temsil hatası bununla sıfırlanmaz. İlk hücre normalliği, LE/TE, aft sütunlar, iz ve dış geçiş ayrı ölçüldü. TE'deki düşey kılavuz dönüşü nedeniyle ilk normalden sapma ençok yaklaşık27°; bu kayıtlı haritalama tercihi ayrıca açık bir sınırdır.</p><img src="../plots/v3_cgrid_medium_regional_mesh.png" alt="Gerçek orta C-grid bölgesel yakın görünümleri"><p><a href="../simulations/v3_cgrid_medium/independent_cgrid_audit.json">Orta ağ ölçümleri</a> · <a href="../simulations/v3_cgrid_fine/independent_cgrid_audit.json">İnce ağ ölçümleri</a></p></section>
<section><h2>Nedenler nasıl ayrıldı?</h2><p>Aynı coarse1000 başlangıcından yalnız CFL politikası, multigrid, entropy sönümü, örtük Jacobian katsayısı ve scalar/matrix JST ayrı dallarda sınandı. Ana fiziksel koşullar, kaynak geometri ve kabul eşikleri değiştirilmedi. Örtük katsayı4→8 aynı ayrık artık denkleminin iterasyon testidir; entropy ve scalar JST ayrık sönümü değiştirir. Scalar/matrix farkını tek bir eigenvalue katsayısına indirgeyemeyiz.</p><p>Bağımsız denetim negatif dual hacim, ters yüz normali veya kopuk bağlantı bulmadı. İlk şok kutusundaki hücre açıları87,51–92,49° ve oranları1,79–3,11; orada “çok ince/kötü hücre” açıklaması desteklenmedi. Kendi alanında normal sütun boyunca Mach zikzakları ölçüldü. Sonraki dallarda en büyük kalıntının konumu değişti; tek eski sıcak kutu bütün vakaların nedeni sayılamaz.</p><img src="../plots/prediction_v3_cgrid_shock_diagnosis_v2.png" alt="Kaynak çözümde ölçülen sayısal alan zikzakları"><p><a href="prediction_v3_cgrid_diagnostic_note.md">Ayrı analizcinin kaynaklı teşhisi</a> · <a href="prediction_v3_cgrid_shock_diagnosis_v2.json">Koordinatlar, ölçüler ve alan hashleri</a></p><p>Jacobian8 tanısında gerçek doğrusal çözücü kayıtları da alındı. İstenen0,05 doğrusal hata toleransına1–2 adımda ulaşılması,15 adım sınırına takılma açıklamasını bu kayıt için desteklemiyor. Daha sıkı doğrusal toleransın ayrı duyarlılık testi yerine geçmez.</p></section>
<section><h2>Kaynak araştırmasının olumsuz sonucu da korundu</h2><p>SU2 doğrulama makalesi RAE2822 için ikinci mertebe türbülans taşınımı kullanıyor; örnek configimiz birinci mertebeydi. Aynı yayımlanmış ağda yalnız bu politika değiştirilerek gerçekten çalıştırıldı. Sonuç deney hatasını iyileştirmedi; daha yüksek mertebe adını otomatik başarı saymadık.</p><p>Yayımlanmış WIND sayısal eğrisi de aynı103 özgün deney noktasına karşı ayrı hesaplandı. Yaklaşık0,05161 RMSE verdi; bu sayısal referans da0,03 hedefimizi karşılamıyor. Bu, eşiği gevşetmez ve bizim kodumuzu doğrulamaz. Yalnız ağ/iterasyon düzeltmesiyle deney farkının mutlaka kapanacağı varsayımına dikkat çeker. Model, fiziksel trip ve tünel düzeltmesi belirsizlikleri ayrı işlerdir; alfa/Mach sonuç tutturmak için oynatılmadı.</p><p>WIND dosyasının yanıltıcı “Experiment” başlığı veri türü sayılmadı. NASA'nın grid sırası ve CFPOST I33..337 seçimiyle alt→üst yüzey düzeni doğrulandı. İlk yanlış yüzey sıralamalı tanı korunup yalnız bu tanı sürümünde düzeltildi; native alanlar ve v1/v2 değerlendirmeleri değişmedi.</p><p><a href="v3_published_WIND_diagnostic.json">Yayımlanmış eğri kıyası</a> · <a href="../data/review/v3_published_WIND_all103.csv">Tüm103 nokta</a></p></section>
<section><h2>Gerçek bulunan ağ üretici hatası</h2><p>İz son noktasını8c'ye doğrudan taşıma, son hücreyi ilan edilen adım tavanının1,384/1,318/1,207 katına çıkarıyordu. Ayrı tail-r2 sürümü kalan uzunluğu kuyruğa eşit dağıtarak düzeltir. Özgün ağlar değiştirilmedi; karşı dallar aynı orijinal ağı kullanır. Bu uzak noktadaki hatanın şok kararsızlığını çözdüğü iddia edilmez.</p><p>Konuma bağlı dış üçgen iyileştirme sürümleri varsa ayrı raporlanır; aynı duvar/normal blok korunarak yeni dış ağ üretilmesi yeni ağ sürümüdür. Geçen geometri denetimi CFD başarısı değildir.</p><p><a href="../simulations/v3_cgrid_tailr2_coarse/independent_cgrid_audit.json">Uygulanmış tail-r2 gerçek ağ denetimi</a> · <a href="prediction_v3_cgrid_unapplied_tail_proposal.json">İlk bağımsız dağıtım önerisi</a></p></section>
<section><h2>LE/TE ve dış ağ geçişinin gerçek düzeltmesi: R3 → R4</h2><p>R3 yalnız iz sonundaki boyut geçişini iyileştirdi; hücum/firar kenarındaki dış üçgen sorunlarını çözmedi. R4 bütün yakın-blok arayüzünün gerçek kenar boyutunu dış ağı boyutlandırmaya katıyor. Etki0,25c içinde tam,0,25–1c arası yumuşak azalan,1c dışında eski boyut kuralıyla aynıdır. Bütün dış üçgenler yeniden üretildiği için bağlantı değişimi bu mesafenin dışına yayılabilir. Duvar, yakın normal blok, kaynak r2 eğrisi ve200c dış sınır korunuyor.</p><div class="scroll"><table><tr><th>Seviye</th><th>R4 hücre</th><th>En büyük çarpıklık önce → sonra</th><th>LE / TE dış-iç normal yükseklik oranı</th><th>Kalan en kötü açı / konum</th></tr>{r4rows}</table></div><p>Tablo bir geometri iyileşmesidir; sonradan geçme eşiği üretilmedi. İnce ağın dış iz bölgesindeki4,95° açısı ve arayüzde kalan normal boyut sıçramaları açık. Bu nedenle bütün aileyi “iyi ağ” veya doğrulanmış CFD diye sunmuyoruz. Aynı noktada pozitif Jacobian/topoloji geçmesi farklı bir kontroldür.</p><img src="../plots/prediction_v3_cgrid_interfacer4_coarse_LE_TE_end_before_after.png" alt="R4 gerçek hücum/firar ve iz ağı önce-sonra"><p><a href="prediction_v3_cgrid_interfacer4_report.md">Üç seviyenin ayrıntılı ağ raporu</a> · <a href="prediction_v3_cgrid_interfacer4_summary.json">Bölgesel normal geçişler</a> · <a href="prediction_v3_cgrid_interfacer4_mesh_manifest.json">Ağ/kod/girdi mühürleri</a></p></section>
<section><h2>Çözücü yöntemi için ayrı kaynaklı denetim</h2><p>Yayımlanmış SU2 RAE2822 çalışmasının sayfa23/33 bölümü JST ve Roe akılarını karşılaştırır; upwind için primitive değişkenlerde Venkatakrishnan sınırlayıcı kullanır. R4'ün ilk merkezi-akı çözümü tekrar yakınsamadığı için aynı mesh ve aynı başlangıç alanında ayrı Roe/MUSCL/sınırlayıcı politikası denetimi kaydedildi. Türbülans taşınımı, fizik, CFL, MG ve doğrusal çözüm bu karşılaştırmada sabittir. Bu politika birden fazla etkin ayarı değiştirir; tek katsayının nedensel testi veya makalenin bire bir yeniden üretimi sayılmaz.</p><p>R4/JST ve R4/Roe ailelerinin ince değerlendirme rolleri çözümlerinden önce ayrı sabitlendi. Daha iyi deney uyumu veren coarse deneme fine yerine geçirilemez. Kaynak makalede daha sıkı doğrusal tolerans her zaman daha hızlı değildi; bizim gerçek LinSolRes kayıtlarımız da “15 adıma takılı kalıyor” varsayımını desteklemiyor.</p><p><a href="v3_research_addendum_02.md">Sonuçtan önce kaydedilen yöntem gerekçesi</a> · <a href="v3_r4_family_plan_seal.json">R4/JST ön seçim</a> · <a href="v3_r4roe_family_plan_seal.json">R4/Roe ön seçim</a></p></section>
<section><h2>Fiziksel koşulların ve kıyasın sınırları</h2><p>Bu vaka NASA'nın önceden seçilmiş düzeltilmiş M0,729/alfa2,31°/Re6,5M koşuludur; nominal deney M0,725/alfa2,92° ile karıştırılmaz. Tam türbülanslı SA-noft2, deneyin x/c0,03 trip telini modellemiyor. Kaynak hesap sıcaklığı255,5556K bir varsayımdır.1m normalize veter için basınç Reynolds benzerliğiyle belirlenir; NASA'nın1ft veterindeki boyutlu basıncı aynen kopyalamıyoruz.</p><p>Kaynak NASA ağ kontrolünde bütün dış kenarlar SU2 FARFIELD'dir; WIND arşivinin ayrı çıkış basıncı sınırı bire bir üretilmedi. Bu nedenle kaynak kod/mesh kontrolünü deneyin veya WIND'in tam yeniden üretimi olarak yorumlamıyoruz. Kabul eşiği0,03 olarak korunur; fizik/model ve deney belirsizliği sayısal yakınsamadan ayrı değerlendirilir.</p><p>Yeni dondurulmuş kıyaslar: {freezes}</p></section>
<section><h2>Kanıtlar ve kapsam</h2><ul><li><a href="v3_research_plan.md">İlk kaynaklı plan</a> ve <a href="v3_research_addendum_01.md">kontrollü tanı ek kaydı</a></li><li><a href="v3_research_plan_seal.json">Plan mührü / değişmeyen kabul SHA</a></li><li><a href="v3_diagnostic_review_01.json">İlk dondurulmuş kıyas</a> · <a href="v3_diagnostic_review_02.json">İkinci kıyas</a></li><li><a href="v3_analytic_gradient_probe_v2.json">Analitik stencil tanısı</a>: NumPy hesabı; native SU2 gradyanı veya fiziksel doğrulama değildir.</li><li><a href="blind_cfd_validation.html">Korunan v1/v2 raporu</a></li></ul><p>Bu sabit RAE2822 benchmark çalışması keyfi CAD'den genel ağ/CFD hizmeti değildir.3D M6, gerçek İHA, stall, kararlılık ve yapı kabulleri kapanmadı. Gerçek İHA girdileri değiştirilmedi. Ağ değişimi, yöntem doğrulaması, farklı çözücü kıyası ve deney doğrulaması ayrı tutulur. Güvenilir monoton/asimptotik rejim kanıtı yokken GCI/Richardson hata bandı verilmez.</p></section><footer>Güncelleme UTC: {now} · Çözümler, config/ağ/alan/geçmiş ve başarısızlık kayıtları proje içinde saklanır.</footer></main></html>'''
    for src,dst in [('work/mesh_research/research_plan.md','v3_research_plan.md'),('work/mesh_research/research_addendum_01.md','v3_research_addendum_01.md'),('work/mesh_research/research_addendum_02.md','v3_research_addendum_02.md'),('work/mesh_research/research_addendum_03.md','v3_research_addendum_03.md')]:shutil.copy2(ROOT/src,REP/dst)
    doc=doc.replace('prediction_v3_cgrid_interfacer4_coarse_LE_TE_end_before_after.png','prediction_v3_cgrid_interfacer4_coarse_LE_TE_end.png')
    doc=doc.replace('Kaynak geometriden kör CFD sınaması projesi · 19 Ekim 2026','Kaynak geometriden kör CFD sınaması projesi · 19–24 Ekim 2026')
    extra='''<section><h2>Rekonstrüksiyon kontrolü ve gerçek alan</h2><p>İkinci mertebe Roe aynı mesh/seed üzerinde kabulü geçmedi. Yalnız MUSCL_FLOW kapatılarak ayrı birinci-mertebe tanı ve kesilen oturumun4200 alanından kontrollü devamı yapıldı. Bu daha fazla sayısal yayınım içeren yöntemdir; daha iyi yakınsama yüksek doğruluk, ikinci mertebe çözüm veya deney kabulü sayılmaz. Bu tanı deney puanına göre aday seçmek için kullanılmadı.</p><p>Yerel VTU residual alanı LinSysRes çalışma vektörüdür; history'deki önceden seçilmiş rms[Rho] kabulüyle eşit olduğu varsayılmadı. Görsel konumsal tanıdır, yakınsama hesabının yerine geçmez.</p><img src="../plots/v3_cgrid_interfacer4_coarse_warmstart_004000_native_fields.png" alt="Gerçek native Mach, Cp ve dışa yazılmış çalışma vektörü"><p><a href="../simulations/v3_field_views/v3_cgrid_interfacer4_coarse_warmstart_004000/native_nearfield.pos">Native Gmsh alanı</a> · <a href="../simulations/v3_field_views/v3_cgrid_interfacer4_coarse_warmstart_004000/field_view_checks.json">SDK ve ayrı Gmsh programıyla geri okuma</a> · <a href="v3_research_addendum_03.md">Etkin yöntem değişimleri</a> · <a href="prediction_v3_cgrid_r4_warmstart_v2_diagnosis.json">Ayrı konumsal alan denetimi</a></p></section>'''
    doc=doc.replace('<section><h2>Kanıtlar ve kapsam</h2>',extra+'<section><h2>Kanıtlar ve kapsam</h2>')
    (REP/'v3_research_diagnosis.html').write_text(doc,encoding='utf-8')
    summary={'updated_utc':now,'project_id':'proje-15cce2de02','report':str((REP/'v3_research_diagnosis.html').relative_to(ROOT)),
        'minimum_qualification_passed':False,'required_missing':['converged three-grid CFD family','regional normal sensitivity and full boundary-layer resolution','controlled farfield200c/400c solve','preselected fine experiment gate'],
        'completed_native_cases':[{k:v for k,v in c.items() if k!='metrics'} for c in cases],
        'old_cases_preserved':True,'new_CAD_designed':False,'scope':'Research-backed fixed benchmark continuation; no general CFD acceptance.'}
    (REP/'v3_research_summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False))
    (ROOT/'outputs/reports/mesh_research_index.json').write_text(json.dumps({'project_id':summary['project_id'],'minimum_qualification_passed':False,'summary':summary['report'],'completed_native_cases':len(cases),'updated_utc':now},indent=2))
    wrapper=f'<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../projects/proje-15cce2de02/reports/v3_research_diagnosis.html"><title>Kaynaklı CFD teşhisi</title><a href="../projects/proje-15cce2de02/reports/v3_research_diagnosis.html">Kaynaklı CFD teşhisi ve gerçek test raporunu aç</a>'
    (ROOT/'outputs/reports/kaynakli_cfd_teshisi.html').write_text(wrapper,encoding='utf-8')
    print(json.dumps({'report':summary['report'],'native_cases':len(cases),'minimum':False},ensure_ascii=False))
